export const PROGRAM_ADDRESS = address("<program>");

// ---- Helpers ----
const concat = (parts: ReadonlyUint8Array[]): Uint8Array => {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of parts) out.set(p, (at += p.length) - p.length);
  return out;
};
const hasPrefix = (data: ReadonlyUint8Array, prefix: ReadonlyUint8Array) => data.length >= prefix.length && prefix.every((b, i) => data[i] === b);
const isSigner = (v: TransactionSigner | Address): v is TransactionSigner => typeof v === "object" && v !== null && "address" in v;
const key = (v: TransactionSigner | Address | undefined | null): Address => {
  if (v === undefined || v === null) throw new Error("a seed account is missing");
  return isSigner(v) ? v.address : v;
};
const required = <T>(v: T | undefined, name: string): T => {
  if (v === undefined) throw new Error("account " + name + " is required");
  return v;
};
const meta = (v: TransactionSigner | Address, role: AccountRole) => (isSigner(v) ? { address: v.address, role, signer: v } : { address: v, role });
const memcmp = (filters: readonly { offset: number; bytes: ReadonlyUint8Array }[]) =>
  filters.map((f) => ({ memcmp: { offset: BigInt(f.offset), bytes: getBase58Decoder().decode(f.bytes) as Base58EncodedBytes, encoding: "base58" as const } }));

// ---- Types ----
export interface Counter {
  authority: Address;
  count: bigint;
  bump: number;
}
export interface CounterArgs {
  authority: Address;
  count: number | bigint;
  bump: number;
}
export function getCounterCodec(): Codec<CounterArgs, Counter> {
  return getStructCodec([["authority", getAddressCodec()], ["count", getU64Codec()], ["bump", getU8Codec()]]) as unknown as Codec<CounterArgs, Counter>;
}

// ---- Accounts ----
const CounterAccount_DISCRIMINATOR = new Uint8Array([255, 176, 4, 245, 188, 253, 124, 25]);
/** Counter account data: the 8-byte discriminator, then the fields. */
const CounterAccount = {
  discriminator: CounterAccount_DISCRIMINATOR,
  decode(data: ReadonlyUint8Array): Counter {
    if (!hasPrefix(data, CounterAccount_DISCRIMINATOR)) throw new Error("not a Counter account (discriminator mismatch)");
    return getCounterCodec().decode(data, 8);
  },
  encode(value: CounterArgs): ReadonlyUint8Array {
    return concat([CounterAccount_DISCRIMINATOR, getCounterCodec().encode(value)]);
  },
  async fetch(rpc: Rpc<GetAccountInfoApi>, at: Address, config?: FetchAccountConfig): Promise<Counter> {
    const found = await fetchEncodedAccount(rpc, at, config);
    if (!found.exists) throw new Error("Counter account does not exist: " + at);
    return CounterAccount.decode(found.data);
  },
  async fetchMaybe(rpc: Rpc<GetAccountInfoApi>, at: Address, config?: FetchAccountConfig): Promise<Counter | null> {
    const found = await fetchEncodedAccount(rpc, at, config);
    return found.exists ? CounterAccount.decode(found.data) : null;
  },
  /** Several accounts in one request, in order; null where one does not exist. */
  async fetchMultiple(rpc: Rpc<GetMultipleAccountsApi>, at: readonly Address[], config?: FetchAccountsConfig): Promise<(Counter | null)[]> {
    const found = await fetchEncodedAccounts(rpc, [...at], config);
    return found.map((a) => (a.exists ? CounterAccount.decode(a.data) : null));
  },
  /** Every Counter account of the program (getProgramAccounts by discriminator), optionally where `bytes` are at `offset` of the data. */
  async fetchAll(rpc: Rpc<GetProgramAccountsApi>, filters: readonly { offset: number; bytes: ReadonlyUint8Array }[] = []): Promise<{ address: Address; data: Counter }[]> {
    const found = await rpc.getProgramAccounts(PROGRAM_ADDRESS, { encoding: "base64", filters: memcmp([{ offset: 0, bytes: CounterAccount_DISCRIMINATOR }, ...filters]) }).send();
    return found.map((a) => ({ address: a.pubkey, data: CounterAccount.decode(getBase64Encoder().encode(a.account.data[0])) }));
  },
  /** Each change of the account, decoded (null once it is closed), until `abortSignal` aborts. */
  async *watch(rpcSubscriptions: RpcSubscriptions<AccountNotificationsApi>, at: Address, options: { abortSignal: AbortSignal; commitment?: Commitment }): AsyncGenerator<Counter | null> {
    const updates = await rpcSubscriptions.accountNotifications(at, { encoding: "base64", ...(options.commitment ? { commitment: options.commitment } : {}) }).subscribe({ abortSignal: options.abortSignal });
    for await (const u of updates) {
      const data = getBase64Encoder().encode(u.value.data[0]);
      yield data.length === 0 ? null : CounterAccount.decode(data);
    }
  },
};

// ---- Instructions ----
export interface InitializeAccounts {
  authority: TransactionSigner | Address;
  counter?: Address;
  systemProgram?: Address;
}
/** Create the caller's counter at PDA ["counter", authority]. */
async function buildInitialize(input: InitializeAccounts, remaining: readonly AccountMeta[] = []): Promise<Instruction> {
  const $authority = input.authority;
  const $systemProgram = input.systemProgram ?? address("11111111111111111111111111111111");
  const $counter = input.counter ?? (await getProgramDerivedAddress({ programAddress: PROGRAM_ADDRESS, seeds: [new Uint8Array([99, 111, 117, 110, 116, 101, 114]), getAddressEncoder().encode(key($authority))] }))[0];
  return {
    programAddress: PROGRAM_ADDRESS,
    accounts: [
      meta(required($authority, "authority"), AccountRole.WRITABLE_SIGNER),
      meta($counter, AccountRole.WRITABLE),
      meta($systemProgram, AccountRole.READONLY),
      ...remaining,
    ],
    data: new Uint8Array([175, 175, 109, 31, 13, 152, 155, 237]),
  } as Instruction;
}

export interface IncrementAccounts {
  authority: TransactionSigner | Address;
  counter: Address;
}
export interface IncrementArgs {
  by: number | bigint;
}
async function buildIncrement(input: IncrementAccounts, args: IncrementArgs, remaining: readonly AccountMeta[] = []): Promise<Instruction> {
  const $authority = input.authority;
  const $counter = input.counter;
  return {
    programAddress: PROGRAM_ADDRESS,
    accounts: [
      meta(required($authority, "authority"), AccountRole.READONLY_SIGNER),
      meta(required($counter, "counter"), AccountRole.WRITABLE),
      ...remaining,
    ],
    data: concat([new Uint8Array([11, 18, 104, 9, 104, 174, 59, 33]), getStructCodec([["by", getU64Codec()]]).encode(args)]),
  } as Instruction;
}

export interface AssertAtLeastAccounts {
  counter: Address;
}
export interface AssertAtLeastArgs {
  min: number | bigint;
}
/** Read-only check that callers can simulate. */
async function buildAssertAtLeast(input: AssertAtLeastAccounts, args: AssertAtLeastArgs, remaining: readonly AccountMeta[] = []): Promise<Instruction> {
  const $counter = input.counter;
  return {
    programAddress: PROGRAM_ADDRESS,
    accounts: [
      meta(required($counter, "counter"), AccountRole.READONLY),
      ...remaining,
    ],
    data: concat([new Uint8Array([217, 17, 64, 130, 131, 210, 58, 81]), getStructCodec([["min", getU64Codec()]]).encode(args)]),
  } as Instruction;
}

